app_css:
.tool-app-passgen-pro { max-width: 560px; color: #064e3b; margin-inline:auto; }
.tool-app-passgen-pro .pg-output-wrap { display: flex; gap: 8px; margin-bottom: 10px; }
.tool-app-passgen-pro #pg-output { flex: 1; border: 2px solid #6ee7b7; border-radius: 10px; padding: 12px; font-family: monospace; font-size: 16px; min-width: 0; }
.tool-app-passgen-pro .pg-btn { background: #10b981; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-weight: 700; cursor: pointer; white-space: nowrap; }
.tool-app-passgen-pro .pg-btn:hover { background: #059669; }
.tool-app-passgen-pro .pg-btn-ghost { background: #d1fae5; color: #065f46; }
.tool-app-passgen-pro .pg-btn-ghost.pg-active { background: #10b981; color: #fff; }
.tool-app-passgen-pro .pg-btn-big { width: 100%; margin: 12px 0; font-size: 16px; }
.tool-app-passgen-pro .pg-meter { height: 10px; background: #d1fae5; border-radius: 5px; overflow: hidden; margin-bottom: 4px; }
.tool-app-passgen-pro .pg-meter-fill { height: 100%; width: 0; border-radius: 5px; transition: width 0.3s; background: #9ca3af; }
.tool-app-passgen-pro .pg-meter-fill.pg-w { background: #ef4444; }
.tool-app-passgen-pro .pg-meter-fill.pg-f { background: #f59e0b; }
.tool-app-passgen-pro .pg-meter-fill.pg-s { background: #3b82f6; }
.tool-app-passgen-pro .pg-meter-fill.pg-e { background: #10b981; }
.tool-app-passgen-pro .pg-strength { font-size: 13px; font-weight: 700; margin-bottom: 12px; }
.tool-app-passgen-pro .pg-modes { display: flex; gap: 8px; margin-bottom: 12px; }
.tool-app-passgen-pro .pg-random-opts label, .tool-app-passgen-pro .pg-pass-opts label { display: flex; align-items: center; gap: 8px; font-size: 14px; margin-bottom: 8px; }
.tool-app-passgen-pro input[type="range"] { accent-color: #10b981; }
.tool-app-passgen-pro .pg-history { list-style: none; padding: 0; margin: 0; }
.tool-app-passgen-pro .pg-history li { margin-bottom: 6px; }
.tool-app-passgen-pro .pg-history button { width: 100%; text-align: left; font-family: monospace; background: #ecfdf5; border: 1px solid #a7f3d0; border-radius: 8px; padding: 8px 10px; cursor: pointer; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tool-app-passgen-pro .pg-history button:hover { background: #d1fae5; }
.tool-app-passgen-pro .pg-hint { font-weight: 400; font-size: 12px; color: #6b7280; }

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  var WORDS = ['apple','river','mango','tiger','cloud','stone','piano','forest',
    'ocean','lemon','eagle','train','garden','moon','star','horse',
    'window','bread','cheese','water','fire','snow','rain','leaf',
    'bird','fish','tree','flower','grass','sun','sky','night',
    'cat','dog','house','car','bike','road','bridge','castle',
    'knight','queen','king','dragon','wizard','pirate','robot','rocket',
    'planet','comet','whale','shark','wolf','bear','fox','owl',
    'frog','crab','shell','grape','peach','melon','honey','ember'];
  var mode = 'random';
  var history = [];
  function randInts(n) {
    var a = new Uint32Array(n);
    (window.crypto || window.msCrypto).getRandomValues(a);
    return a;
  }
  function strip(s, chars) {
    var out = '';
    for (var i = 0; i < s.length; i++) {
      if (chars.indexOf(s[i]) === -1) out += s[i];
    }
    return out;
  }
  function generate() {
    var out, bits;
    if (mode === 'random') {
      var up = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
      var lo = 'abcdefghijklmnopqrstuvwxyz';
      var dg = '0123456789';
      var sy = '!@#$%^&*()-_=+[]{};:,.<>?';
      if ($('pg-ambiguous').checked) {
        var amb = 'il1Lo0O';
        up = strip(up, amb); lo = strip(lo, amb); dg = strip(dg, amb);
      }
      var sets = [];
      if ($('pg-upper').checked) sets.push(up);
      if ($('pg-lower').checked) sets.push(lo);
      if ($('pg-digits').checked) sets.push(dg);
      if ($('pg-symbols').checked) sets.push(sy);
      if (!sets.length) sets.push(lo);
      var chars = sets.join('');
      var len = parseInt($('pg-length').value, 10) || 16;
      var r = randInts(len);
      var s = '';
      for (var i = 0; i < len; i++) s += chars.charAt(r[i] % chars.length);
      out = s;
      bits = len * (Math.log(chars.length) / Math.LN2);
    } else {
      var n = parseInt($('pg-words').value, 10) || 4;
      var r2 = randInts(n);
      var parts = [];
      for (var j = 0; j < n; j++) parts.push(WORDS[r2[j] % WORDS.length]);
      out = parts.join('-');
      bits = n * (Math.log(WORDS.length) / Math.LN2);
    }
    $('pg-output').value = out;
    showStrength(bits);
    pushHistory(out);
  }
  function showStrength(bits) {
    var label, pct, cls;
    if (bits < 40) { label = 'Weak'; pct = 25; cls = 'pg-w'; }
    else if (bits < 60) { label = 'Fair'; pct = 50; cls = 'pg-f'; }
    else if (bits < 90) { label = 'Strong'; pct = 75; cls = 'pg-s'; }
    else { label = 'Excellent'; pct = 100; cls = 'pg-e'; }
    $('pg-strength').textContent = label + ' · about ' + Math.round(bits) + ' bits of entropy';
    var f = $('pg-meterfill');
    f.style.width = pct + '%';
    f.className = 'pg-meter-fill ' + cls;
  }
  function flashCopied() {
    var b = $('pg-copy');
    var old = b.textContent;
    b.textContent = 'Copied ✓';
    setTimeout(function () { b.textContent = old; }, 1200);
  }
  function copyText(t) {
    function fallback() {
      var ta = document.createElement('textarea');
      ta.value = t;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); } catch (e) {}
      document.body.removeChild(ta);
      flashCopied();
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(t).then(flashCopied, fallback);
    } else {
      fallback();
    }
  }
  function renderHistory() {
    var ul = $('pg-history');
    ul.innerHTML = '';
    history.forEach(function (h) {
      var li = document.createElement('li');
      var b = document.createElement('button');
      b.type = 'button';
      b.textContent = h;
      b.title = 'Click to copy';
      b.addEventListener('click', function () { copyText(h); });
      li.appendChild(b);
      ul.appendChild(li);
    });
  }
  function pushHistory(t) {
    history.unshift(t);
    history = history.slice(0, 10);
    renderHistory();
  }
  function setMode(m) {
    mode = m;
    $('pg-mode-random').classList.toggle('pg-active', m === 'random');
    $('pg-mode-pass').classList.toggle('pg-active', m === 'pass');
    $('pg-randomopts').hidden = (m !== 'random');
    $('pg-passopts').hidden = (m !== 'pass');
  }
  $('pg-generate').addEventListener('click', generate);
  $('pg-copy').addEventListener('click', function () {
    var v = $('pg-output').value;
    if (v) copyText(v);
  });
  $('pg-mode-random').addEventListener('click', function () { setMode('random'); });
  $('pg-mode-pass').addEventListener('click', function () { setMode('pass'); });
  $('pg-length').addEventListener('input', function () { $('pg-lenval').textContent = $('pg-length').value; });
  $('pg-words').addEventListener('input', function () { $('pg-wordsval').textContent = $('pg-words').value; });
  setMode('random');
  generate();
})();
